function n(t){return t<10?"0"+t:""+t}function g(t){if(!t)return"-";const e=new Date(t);return Number.isNaN(e.getTime())?"-":`${e.getFullYear()}-${n(e.getMonth()+1)}-${n(e.getDate())} ${n(e.getHours())}:${n(e.getMinutes())}:${n(e.getSeconds())}`}function m(t,e){if(!t)return"-";const s=new Date(t).getTime(),o=e?new Date(e).getTime():Date.now();if(Number.isNaN(s)||Number.isNaN(o))return"-";const r=Math.max(0,Math.round((o-s)/1e3));if(r<60)return`${r}秒`;const a=Math.floor(r/60),u=r%60;return a<60?`${a}分${u}秒`:`${Math.floor(a/60)}时${a%60}分${u}秒`}const i={success:{text:"成功",type:"success"},failed:{text:"失败",type:"danger"},running:{text:"运行中",type:"primary"},pending:{text:"等待中",type:"info"},stopped:{text:"已停止",type:"warning"}};function y(t){return i[t]||{text:t||"未知",type:"info"}}const c={ok:{text:"同步成功",type:"success"},error:{text:"同步失败",type:"danger"},never:{text:"从未同步",type:"info"}};function x(t){return c[t]||{text:t||"未知",type:"info"}}const f=/\x1b\[[0-9;]*m/g;function $(t){return t?t.replace(f,""):""}export{m as a,x as b,g as f,$ as s,y as t};
